qa={'base_archive_sha256':hashlib.sha256(base.read_bytes()).hexdigest(),'archive_sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'changed_game_files':changed,'six_other_files_identical':True,'original_implementation_bytes_preserved':True,'original_MM_renderer_preserved':True,'prices_payment_and_virtual_improve_call_unchanged':True,'added_upgrade_counter':False,'service_counters_modified':False,'read_only_comparison_checks':json.loads((ROOT/'QA_comparison.json').read_text())['passed'],'native_station_and_display_checks':json.loads((ROOT/'QA_station.json').read_text())['passed'],'installation_checks':json.loads((ROOT/'QA_installation.json').read_text())['passed'],'live_game_test':False}
